export function portfolioSources(id: PortfolioPhotoId) {
  const photo = PORTFOLIO_PHOTOS[id]
  const widths = photo.widths ?? PORTFOLIO_WIDTHS
  const srcSet = (ext: "avif" | "jpg") =>
    widths.map((w) => `/media/portfolio/${id}-${w}.${ext} ${w}w`).join(", ")
  const largest = widths[widths.length - 1]
  return {
    src: `/media/portfolio/${id}-${largest}.jpg`,
    avif: srcSet("avif"),
    jpg: srcSet("jpg"),
    width: photo.width,
    height: photo.height,
  }
}
